// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 drugs) public {
        vm.assume(drugs > 0);
        address ceo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        vm.prank(ceo);
        c.DrugDealer();
        c.seedMarket(drugs);
        assertTrue(c.marketDrugs() > 0);
    }
}

